import java.util.ArrayList;
import java.util.ConcurrentModificationException;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

public class Main {
    static final int THREADS = 8;
    static final int PER = 20000;

    static void runAll(Runnable body) throws Exception {
        Thread[] ts = new Thread[THREADS];
        for (int i = 0; i < THREADS; i++) { ts[i] = new Thread(body); ts[i].start(); }
        for (Thread t : ts) t.join();
    }

    public static void main(String[] args) throws Exception {
        int expect = THREADS * PER;

        ConcurrentHashMap<String, Integer> good = new ConcurrentHashMap<>();
        runAll(() -> { for (int i = 0; i < PER; i++) good.merge("hits", 1, Integer::sum); });
        System.out.println("CHM merge()       exact : " + (good.get("hits") == expect));

        ConcurrentHashMap<String, Integer> bad = new ConcurrentHashMap<>();
        runAll(() -> {
            for (int i = 0; i < PER; i++) {
                Integer old = bad.get("hits");
                bad.put("hits", old == null ? 1 : old + 1);
            }
        });
        System.out.println("CHM get()+put()   lost  : " + (bad.getOrDefault("hits", 0) < expect));

        ConcurrentHashMap<String, List<Integer>> trap = new ConcurrentHashMap<>();
        runAll(() -> {
            for (int i = 0; i < 100; i++) {
                trap.computeIfAbsent("g" + (i % 4), k -> new ArrayList<>()).add(i);
            }
        });
        int trapTotal = 0;
        for (List<Integer> l : trap.values()) trapTotal += l.size();
        System.out.println("computeIfAbsent + ArrayList lost  : " + (trapTotal < THREADS * 100));

        ConcurrentHashMap<String, List<Integer>> safe = new ConcurrentHashMap<>();
        runAll(() -> {
            for (int i = 0; i < 100; i++) {
                safe.computeIfAbsent("g" + (i % 4), k -> new CopyOnWriteArrayList<>()).add(i);
            }
        });
        int safeTotal = 0;
        for (List<Integer> l : safe.values()) safeTotal += l.size();
        System.out.println("computeIfAbsent + COWList  exact  : " + (safeTotal == THREADS * 100));

        ConcurrentHashMap<Integer, Integer> weak = new ConcurrentHashMap<>();
        for (int i = 0; i < 10; i++) weak.put(i, i);
        boolean cme = false;
        try { for (Integer k : weak.keySet()) weak.put(100 + k, 1); }
        catch (ConcurrentModificationException e) { cme = true; }
        System.out.println("CHM iterator      no CME: " + !cme);

        HashMap<Integer, Integer> fast = new HashMap<>();
        for (int i = 0; i < 10; i++) fast.put(i, i);
        boolean cme2 = false;
        try { for (Integer k : fast.keySet()) { if (k == 3) fast.put(99, 1); } }
        catch (ConcurrentModificationException e) { cme2 = true; }
        System.out.println("HashMap iterator  fail-fast CME : " + cme2);

        CopyOnWriteArrayList<Integer> cow = new CopyOnWriteArrayList<>(List.of(1, 2, 3));
        Iterator<Integer> it = cow.iterator();
        cow.add(4);
        cow.add(5);
        int snapshot = 0;
        while (it.hasNext()) { it.next(); snapshot++; }
        System.out.println("COW snapshot size = " + snapshot + ", live list size = " + cow.size());
    }
}
